(window.BOOKS ||= []).push({"id":"datos","title":"Datos y APIs","subtitle":"SQL, REST, FastAPI, Django y Docker","cover":["#b79bff","#ff9ac2"],"chapters":[{"title":"SQL: fundamentos y estructura","concepts":[{"title":"DDL, DML, DQL y DCL","que":[{"t":"p","x":"DDL define estructura (`CREATE`, `ALTER`, `DROP`); DML manipula datos (`INSERT`, `UPDATE`, `DELETE`); DQL consulta (`SELECT`); DCL gestiona permisos (`GRANT`, `REVOKE`)."}],"ejemplo":[],"qa":[{"q":"¿A qué familia pertenece `ALTER TABLE` y a cuál `UPDATE`?","a":"`ALTER` es DDL; `UPDATE` es DML."}]},{"title":"CRUD","que":[{"t":"p","x":"Las cuatro operaciones básicas sobre datos: Crear, Leer, Actualizar, Borrar (Create, Read, Update, Delete). En SQL: INSERT, SELECT, UPDATE, DELETE; en HTTP: POST, GET, PUT/PATCH, DELETE."}],"ejemplo":[],"qa":[{"q":"¿Qué significa CRUD?","a":"Crear, Leer, Actualizar y Borrar datos."}]},{"title":"Tipos de datos esenciales","que":[{"t":"p","x":"`INT` enteros; `DECIMAL(10,2)` números exactos con decimales (dinero); `VARCHAR(n)` texto corto; `TEXT` texto largo; `DATE`/`DATETIME` fechas; `BOOLEAN` lógicos. Evitar `FLOAT`/`DOUBLE` para dinero."}],"ejemplo":[],"qa":[{"q":"¿Qué tipo usas para precios y por qué?","a":"`DECIMAL(10,2)`: guarda valores exactos sin errores de redondeo."}]},{"title":"Constraints","que":[{"t":"p","x":"`NOT NULL` obliga valor; `DEFAULT` valor por defecto; `UNIQUE` sin duplicados; `CHECK (price > 0)` valida condición; `FOREIGN KEY ... REFERENCES` vincula tablas; `PRIMARY KEY` identifica la fila (una relación 1 a 1 usa `user_id` como PK+FK). Al violarlas, Postgres avisa `violates check/unique/foreign key/not-null constraint`."}],"ejemplo":[{"t":"p","x":"`price DECIMAL(10,2) CHECK (price > 0)`"}],"qa":[{"q":"¿Qué constraint impide registrar un precio negativo?","a":"`CHECK (price > 0)`."}]},{"title":"Atributos de columna","que":[{"t":"p","x":"`AUTO_INCREMENT` (uno por tabla, ligado a PRIMARY KEY o UNIQUE), `DEFAULT (CURRENT_DATE)`, `COMMENT`, columnas calculadas `GENERATED ALWAYS AS (...) STORED/VIRTUAL`, `CHARACTER SET/COLLATE`, `ZEROFILL` (poco usado)."}],"ejemplo":[{"t":"p","x":"`id INT AUTO_INCREMENT PRIMARY KEY`"}],"qa":[{"q":"¿Cuántos `AUTO_INCREMENT` admite una tabla y a qué debe asociarse?","a":"Uno; a una PRIMARY KEY o UNIQUE."}]},{"title":"CREATE/DROP DATABASE y USE","que":[{"t":"p","x":"`CREATE DATABASE` crea la base, `USE` la selecciona y `DROP DATABASE` la elimina junto con todas sus tablas (cuidado en producción). `SHOW TABLES` lista las tablas."}],"ejemplo":[],"qa":[{"q":"¿Qué borra `DROP DATABASE ecommerce;`?","a":"La base de datos entera con todas sus tablas."}]},{"title":"Clave primaria, clave foránea, integridad referencial y normalización","que":[{"t":"p","x":"La PK identifica de forma única una fila; la FK (`FOREIGN KEY (user_id) REFERENCES users(id)`) referencia la PK de otra tabla y asegura integridad referencial (el valor debe existir; evita huérfanos). `CREATE TABLE` define columnas, constraints y relaciones. La normalización (1FN, 2FN, 3FN) evita duplicar datos."}],"ejemplo":[],"qa":[{"q":"¿Qué garantiza una clave foránea?","a":"Integridad referencial: el valor referenciado debe existir en la otra tabla (relaciones consistentes, sin huérfanos)."}]},{"title":"ALTER TABLE","que":[{"t":"p","x":"Modifica la estructura sin eliminar la tabla: `ADD COLUMN`, `DROP COLUMN`, `RENAME COLUMN a TO b`, `MODIFY COLUMN`, `ADD CONSTRAINT`, `DROP CONSTRAINT`, `RENAME TO`, `ADD/DROP INDEX`, `ADD/DROP CHECK`. `DESCRIBE tabla` verifica el resultado."}],"ejemplo":[{"t":"p","x":"`ALTER TABLE users ADD COLUMN phone VARCHAR(20);`"}],"qa":[{"q":"¿Qué comando cambia el tipo o NOT NULL de una columna sin renombrarla?","a":"`ALTER TABLE t MODIFY COLUMN col tipo ...;`"}]},{"title":"DELETE vs TRUNCATE vs DROP","que":[{"t":"p","x":"`DELETE` borra filas concretas (con WHERE); `TRUNCATE TABLE` vacía todas las filas manteniendo la estructura (más rápido); `DROP TABLE` elimina la tabla entera."}],"ejemplo":[],"qa":[{"q":"¿Qué diferencia hay entre TRUNCATE y DROP TABLE?","a":"TRUNCATE vacía los datos y conserva la estructura; DROP elimina la tabla."}]}]},{"title":"SQL: insertar, actualizar y transacciones","concepts":[{"title":"INSERT INTO","que":[{"t":"p","x":"`INSERT INTO tabla (cols) VALUES (...), (...)` inserta varias filas a la vez. Se pueden omitir columnas con `DEFAULT` o que aceptan `NULL`; `NULL` marca valor desconocido."}],"ejemplo":[],"qa":[{"q":"¿Cómo insertas varias filas en una sola sentencia?","a":"Separando las tuplas de `VALUES` con comas."}]},{"title":"UPDATE y DELETE siempre con WHERE","que":[{"t":"p","x":"`UPDATE t SET c1=v1, c2=v2 WHERE id=3` modifica varias columnas de una fila; sin `WHERE` afecta todas las filas. Igual con `DELETE`."}],"ejemplo":[],"qa":[{"q":"¿Qué pasa si olvidas el WHERE en un UPDATE o DELETE?","a":"Se modifican o borran todas las filas de la tabla."}]},{"title":"Transacciones: begin / commit / rollback como red de seguridad","que":[{"t":"p","x":"Todo cambio de datos en una BD real conviene probarlo dentro de `begin; ... rollback;` (o `commit;`) con `returning *` y un `select` de comprobación: nadie ve el cambio hasta el commit. Es como `git stash`. Si el cambio \"no se guardó\", faltó `commit`. Tras un error la transacción queda inservible hasta el `rollback`. Una transacción garantiza todo o nada (ver sign-up en GYM)."}],"ejemplo":[],"qa":[{"q":"¿Cómo probar un UPDATE sin riesgo?","a":"Dentro de `begin;` revisando con `select`; luego `rollback;` para deshacer o `commit;` para guardar."}]}]},{"title":"SQL: consultas SELECT","concepts":[{"title":"SELECT, columnas y WHERE","que":[{"t":"p","x":"`SELECT *` trae todas las columnas; listar columnas concretas mejora claridad y rendimiento; `WHERE` filtra filas; se combinan condiciones con `AND`/`OR`."}],"ejemplo":[{"t":"p","x":"`SELECT name, price, stock FROM products WHERE stock >= 10 AND price > 10;`"}],"qa":[{"q":"¿Qué hace `SELECT *`?","a":"Devuelve todas las columnas de la tabla."}]},{"title":"Operadores de comparación","que":[{"t":"p","x":"`=`, `<`, `>`, `<=`, `>=`, `<>`/`!=`, `BETWEEN a AND b` (inclusivo), `LIKE '%mo%'` (comodín `%`), `IN (1,2,3)`, `IS NULL`, `IS NOT NULL`."}],"ejemplo":[],"qa":[{"q":"¿Cómo buscas filas sin descripción: `= NULL` o `IS NULL`?","a":"`IS NULL` (NULL no se compara con `=`)."}]},{"title":"ORDER BY, LIMIT y DISTINCT","que":[{"t":"p","x":"`ORDER BY col ASC|DESC` ordena; `LIMIT n` trae los primeros n; `DISTINCT` elimina filas duplicadas (sobre la combinación de columnas)."}],"ejemplo":[],"qa":[{"q":"¿Cómo obtienes el top 3 por puntaje?","a":"`ORDER BY puntaje DESC LIMIT 3`."}]},{"title":"Alias con AS","que":[{"t":"p","x":"`AS` renombra columnas en el resultado (`price AS precio`) y tablas (`users AS u`), muy útil en joins y reportes."}],"ejemplo":[],"qa":[{"q":"¿Para qué sirve un alias de tabla en un JOIN?","a":"Acorta y desambigua los nombres de tabla."}]},{"title":"Funciones de agregación","que":[{"t":"p","x":"`COUNT`, `SUM`, `AVG`, `MIN`, `MAX` calculan sobre un conjunto de filas y devuelven un solo valor; se combinan con `WHERE` y varias en la misma consulta."}],"ejemplo":[{"t":"p","x":"`SELECT COUNT(*), AVG(price), SUM(stock) FROM products;`"}],"qa":[{"q":"¿Qué devuelve `COUNT(*)` y qué función da el promedio?","a":"El número de filas; `AVG()`."}]},{"title":"GROUP BY (agrupar por id, no por nombre)","que":[{"t":"p","x":"Agrupa filas por una o más columnas para aplicar agregaciones por grupo (ventas por usuario, reseñas por película). Conviene agrupar por la clave primaria (`c.id`) y no solo por nombre: si dos registros comparten nombre, agrupar por nombre los fusionaría. `ORDER BY total DESC LIMIT 3` da el top 3."}],"ejemplo":[],"qa":[{"q":"¿Por qué agrupar por `c.id` y no por `c.nombre`?","a":"Porque pueden existir nombres repetidos y agrupar por nombre fusionaría clientes distintos."}]},{"title":"HAVING vs WHERE","que":[{"t":"p","x":"`WHERE` filtra filas antes de agrupar; `HAVING` filtra los grupos ya agregados (`HAVING COUNT(r.id) > 1`, o `GROUP BY email HAVING COUNT(*) > 1` para hallar duplicados)."}],"ejemplo":[],"qa":[{"q":"¿Cuándo usas HAVING en lugar de WHERE?","a":"Para filtrar sobre resultados agregados tras GROUP BY; WHERE filtra filas previas al agrupamiento."}]},{"title":"ROUND y COUNT(DISTINCT)","que":[{"t":"p","x":"`ROUND(AVG(x), 2)` redondea promedios; `COUNT(DISTINCT col)` cuenta valores distintos (juegos distintos por usuario)."}],"ejemplo":[],"qa":[{"q":"¿Cómo cuentas los juegos distintos que jugó cada usuario?","a":"`COUNT(DISTINCT s.game_id)` con `GROUP BY` usuario."}]},{"title":"COALESCE y el NULL de un LEFT JOIN","que":[{"t":"p","x":"`COALESCE(expr, valor)` devuelve el primer valor no nulo; típico para convertir un `SUM` nulo (usuario sin pedidos, provincia sin ventas tras un LEFT JOIN sin coincidencia) en 0."}],"ejemplo":[{"t":"p","x":"`SELECT c.provincia, COALESCE(SUM(p.monto),0) FROM clientes c LEFT JOIN pedidos p ON p.cliente_id=c.id GROUP BY c.provincia`"}],"qa":[{"q":"¿Qué hace `COALESCE(SUM(total), 0)` y cuándo hace falta?","a":"Sustituye el NULL por 0 si no hay filas, p. ej. sobre un LEFT JOIN sin coincidencias."}]}]},{"title":"SQL: JOINs, subconsultas y ventanas","concepts":[{"title":"INNER JOIN","que":[{"t":"p","x":"Combina tablas solo cuando hay coincidencia en la condición `ON` (PK = FK). Se encadenan varios para unir 3 o más tablas. `JOIN` equivale a `INNER JOIN`."}],"ejemplo":[{"t":"p","x":"`FROM users u JOIN orders o ON u.id = o.user_id`"}],"qa":[{"q":"¿Qué filas devuelve un INNER JOIN?","a":"Solo las que tienen coincidencia en ambas tablas."}]},{"title":"LEFT JOIN, RIGHT JOIN y FULL JOIN","que":[{"t":"p","x":"`LEFT JOIN` devuelve todas las filas de la tabla izquierda más las coincidencias de la derecha (o NULL si no hay); `RIGHT JOIN` al revés; `FULL JOIN` conserva todo de ambos lados. Formas completas: LEFT/RIGHT OUTER JOIN. INNER conserva solo coincidencias."}],"ejemplo":[],"qa":[{"q":"Quieres todos los clientes aunque no tengan pedidos: ¿qué JOIN, y qué valores aparecen en las columnas de `orders` de quien no tiene?","a":"`LEFT JOIN` desde clientes hacia pedidos; las columnas de pedidos salen `NULL`."}]},{"title":"Anti-join: detectar ausencias","que":[{"t":"p","x":"`LEFT JOIN ... WHERE o.id IS NULL` devuelve solo filas de la izquierda sin coincidencia (usuarios/clientes sin pedidos); alternativas `NOT EXISTS` o `NOT IN`. Un RIGHT JOIN sirve para encontrar pedidos huérfanos."}],"ejemplo":[],"qa":[{"q":"¿Cómo encuentras filas de A sin pareja en B?","a":"`A LEFT JOIN B ... WHERE B.id IS NULL` (o `NOT EXISTS`)."}]},{"title":"Un JOIN puede duplicar filas e inflar totales","que":[{"t":"p","x":"Una relación uno-a-muchos repite la fila del lado \"uno\" por cada fila del lado \"muchos\"; sumar después infla totales. Se evita agregando antes del JOIN, agrupando por la clave correcta o con DISTINCT/subconsultas."}],"ejemplo":[],"qa":[{"q":"¿Por qué un JOIN puede inflar un SUM?","a":"Porque repite filas del lado uno por cada coincidencia del lado muchos, y se suman varias veces."}]},{"title":"Relación muchos a muchos con tabla intermedia","que":[{"t":"p","x":"Se modela con una tabla puente (castings: movie_id + actor_id) con clave primaria compuesta y dos FKs; se consulta uniendo tres tablas."}],"ejemplo":[],"qa":[{"q":"¿Cómo se modela una relación muchos-a-muchos?","a":"Con una tabla intermedia con clave compuesta y dos claves foráneas."}]},{"title":"Subconsulta correlacionada y derivada","que":[{"t":"p","x":"Una subconsulta en el SELECT que referencia la fila externa (`WHERE user_id = u.id`) se ejecuta por fila (puede ser lenta); una subconsulta derivada en `FROM (...) AS resumen` permite filtrar después de agrupar."}],"ejemplo":[],"qa":[{"q":"¿Qué es una subconsulta derivada?","a":"Una consulta en la cláusula FROM con alias, usada como tabla."}]},{"title":"Funciones ventana vs GROUP BY","que":[{"t":"p","x":"Una función ventana (`SUM() OVER (PARTITION BY ...)`) calcula agregados sin colapsar filas; GROUP BY reduce a una fila por grupo."}],"ejemplo":[],"qa":[{"q":"¿En qué se diferencia una función ventana de GROUP BY?","a":"La ventana mantiene todas las filas y añade el cálculo; GROUP BY colapsa cada grupo en una fila."}]},{"title":"Agrupar por mes con substr y total cantidad×precio","que":[{"t":"p","x":"Para agrupar fechas ISO guardadas como texto por mes: `substr(fecha, 1, 7)` (YYYY-MM); el total se calcula como `SUM(cantidad * precio)`."}],"ejemplo":[],"qa":[{"q":"¿Cómo agrupas ventas por mes si la fecha es texto `YYYY-MM-DD`?","a":"`GROUP BY substr(fecha, 1, 7)`."}]}]},{"title":"SQL: diseño, índices e integridad","concepts":[{"title":"Índices","que":[{"t":"p","x":"Estructura auxiliar que acelera búsquedas/joins sobre una columna a cambio de espacio y escrituras más lentas. Un índice UNIQUE además impone unicidad."}],"ejemplo":[],"qa":[{"q":"¿Qué costo tiene un índice?","a":"Más espacio y INSERT/UPDATE más lentos, a cambio de lecturas más rápidas."}]},{"title":"ENUM, índices y motor","que":[{"t":"p","x":"`ENUM` para estados fijos (evitar si el conjunto crece: usar tabla de referencia); indexar siempre las claves foráneas; `ENGINE=InnoDB` (transacciones y FKs); `utf8mb4` para Unicode y emojis; nombres `snake_case`; no `TEXT` en campos muy filtrados; clave compuesta para evitar duplicados en tablas puente."}],"ejemplo":[],"qa":[{"q":"¿Por qué usar InnoDB y utf8mb4?","a":"InnoDB soporta transacciones y FKs; utf8mb4 soporta todo Unicode."}]},{"title":"Índice UNIQUE y deduplicación de URLs","que":[{"t":"p","x":"`CREATE UNIQUE INDEX IF NOT EXISTS idx_products_url_unique ON products(url)` impide duplicados; se captura `IntegrityError`. Además se comprueba existencia antes de insertar (`SELECT 1 ... WHERE url=?`)."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas productos duplicados por URL?","a":"Con un índice UNIQUE en `url` y comprobando existencia antes de insertar."}]},{"title":"Clave primaria y tipos sin signo","que":[{"t":"p","x":"`id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY`; `UNSIGNED` evita negativos y amplía el rango positivo (precios, stock, salarios)."}],"ejemplo":[],"qa":[{"q":"¿Qué ventaja da `UNSIGNED` en un campo de stock?","a":"Evita negativos y duplica el rango positivo."}]},{"title":"Contraseñas, emails y booleanos","que":[{"t":"p","x":"`email VARCHAR(255) UNIQUE NOT NULL`; `password VARCHAR(255)` para hashes (bcrypt/argon2), nunca texto plano; booleanos con `DEFAULT` lógico y sin NULL (`is_active BOOLEAN DEFAULT TRUE`); teléfonos como VARCHAR (pueden llevar `+`)."}],"ejemplo":[],"qa":[{"q":"¿Por qué el teléfono se guarda como VARCHAR y no numérico?","a":"Puede llevar `+`, `-` y espacios."}]},{"title":"Auditoría: created_at / updated_at","que":[{"t":"p","x":"`created_at DATETIME DEFAULT CURRENT_TIMESTAMP` y `updated_at ... ON UPDATE CURRENT_TIMESTAMP` dan trazabilidad automática; también `created_by`, `updated_by`, `version`. En Postgres `updated_at` se mantiene con un trigger (`set_updated_at`)."}],"ejemplo":[],"qa":[{"q":"¿Cómo se actualiza `updated_at` automáticamente?","a":"`DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP` (MySQL) o un trigger (Postgres)."}]},{"title":"Borrado lógico (soft delete)","que":[{"t":"p","x":"Marcar `deleted BOOLEAN`/`deleted_at`/`active=false`/`available=false` en vez de borrar físicamente conserva el historial y permite sincronizar bajas; hay que filtrar `where active`. Baja lógica = UPDATE; baja física = DELETE. Ej. GYM: no hay DELETE de ejercicios (romperían el historial; se marcan `available=false`) y `roles` es un array validado con `check` (MEMBER, TRAINER, ADMIN, no vacío); solo `DELETE /me` borra en cascada."}],"ejemplo":[],"qa":[{"q":"¿Qué diferencia hay entre baja lógica y baja física, y por qué no borrar ejercicios?","a":"La lógica marca el registro como inactivo (UPDATE); la física lo elimina. Borrar ejercicios rompería el historial."}]},{"title":"ON DELETE CASCADE / SET NULL","que":[{"t":"p","x":"`ON DELETE CASCADE` borra los dependientes (al borrar el padre se borran las filas hijas); `ON DELETE SET NULL` los conserva sin asignación. Elegir según dependencia (pedidos de un usuario vs empleado de un departamento)."}],"ejemplo":[],"qa":[{"q":"¿Cuándo usar `SET NULL` en lugar de `CASCADE`?","a":"Cuando el hijo debe sobrevivir sin el padre (empleado sin departamento)."}]},{"title":"Diseño de esquema sincronizable y multi-tenant: uuid, updated_at, gym_id","que":[{"t":"p","x":"IDs `uuid` (el cliente/teléfono crea registros sin conexión sin chocar IDs y el reintento no duplica); `updated_at` con trigger en todas las tablas (sync incremental y auditoría); `gym_id` en todo (multi-gimnasio/tenant); copia privada de la rutina al asignarla (editar la plantilla no cambia lo ya asignado); `gym_today()` calcula \"hoy\" en la zona horaria del gimnasio; permisos en la API en lugar de RLS."}],"ejemplo":[],"qa":[{"q":"¿Qué ventaja da usar uuid en vez de enteros autoincrementales?","a":"El teléfono puede crear registros sin conexión sin chocar IDs, y el reintento no duplica."}]},{"title":"Manejo de nulos, vacíos y duplicados en datos","que":[{"t":"p","x":"En limpieza de datos hay que decidir cómo tratar nulos (descartar, imputar, `COALESCE`), vacíos y duplicados (conservar el primero) y registrar lo rechazado."}],"ejemplo":[],"qa":[{"q":"¿Cómo tratas ids duplicados al cargar un CSV?","a":"Se conserva la primera aparición y las demás se envían a \"rechazadas\"."}]},{"title":"Entorno de práctica de SQL","que":[{"t":"p","x":"MySQL (puerto 3306, usuario root) y PostgreSQL (puerto 5432, usuario postgres) corren con Docker/DBngin y se inspeccionan con TablePlus; runsql.com sirve de playground sin instalar."}],"ejemplo":[],"qa":[{"q":"¿Puertos por defecto de MySQL y PostgreSQL?","a":"3306 y 5432."}]}]},{"title":"PostgreSQL, SQLite y operación de bases de datos","concepts":[{"title":"SQLite vs PostgreSQL: por qué Postgres necesita servidor","que":[{"t":"p","x":"Con varios escritores concurrentes y sin árbitro se corrompe el archivo. Alguien debe SERIALIZAR los accesos y no puede confiarse a los clientes. SQLite lo resuelve más barato con un candado y un solo escritor a la vez: sirve para escritorio/desarrollo, no para cien usuarios web."}],"ejemplo":[],"qa":[{"q":"¿Qué problema concreto obliga a Postgres a tener un proceso servidor?","a":"Serializar los accesos concurrentes para que dos escritores no corrompan los datos."}]},{"title":"Jerarquía de Postgres: instancia → base → esquema → tabla","que":[{"t":"p","x":"`\\l` lista las bases de datos de la instancia; `\\dt` lista las tablas de la base actual. La jerarquía: instancia (servidor en un puerto) → base de datos (aisladas entre sí) → esquema (`public` por defecto) → tabla."}],"ejemplo":[],"qa":[{"q":"¿Qué diferencia hay entre `\\l` y `\\dt`?","a":"`\\l` lista bases de datos; `\\dt` lista tablas de la base actual."}]},{"title":"psql: conexión, meta-comandos y dónde estoy conectado","que":[{"t":"p","x":"`psql \"postgres://USUARIO:CLAVE@HOST:PUERTO/BASE\"` o `docker exec -it backend-db-1 psql -U gym -d gym`. Meta-comandos con `\\`: `\\l` bases, `\\c` cambiar, `\\dt` tablas, `\\d tabla` estructura, `\\di` índices, `\\df` funciones, `\\x` vista vertical, `\\timing`, `\\i archivo.sql`, `\\conninfo` (host, puerto, base, usuario), `\\q`. `SELECT version();` revela el sistema (Visual C++ = Postgres nativo de Windows; `x86_64-pc-linux-gnu` = contenedor Docker). El SQL termina en `;` (si falta, el prompt queda en `gym-#`). Trampa: dos Postgres (5432 y 5433); usar `127.0.0.1` evita IPv6 `::1`. En PowerShell configurar UTF-8 (`chcp 65001`, `$env:PGCLIENTENCODING=\"UTF8\"`)."}],"ejemplo":[],"qa":[{"q":"¿Qué comando muestra la estructura de una tabla y cuál te dice a qué Postgres estás conectado?","a":"`\\d nombre_tabla`; `\\conninfo` y `select version();`."}]},{"title":"Consultas específicas de PostgreSQL (ILIKE, any, DISTINCT ON, filter, date_trunc)","que":[{"t":"p","x":"`ILIKE '%txt%'` (like sin distinguir mayúsculas), `'TRAINER' = any(roles)` para arrays, `DISTINCT ON` da el último registro por grupo, `filter (where ...)`, `exists`, `date_trunc`, `at time zone`, `interval`, además de `JOIN`/`LEFT JOIN`/`GROUP BY`/subconsultas."}],"ejemplo":[{"t":"code","lang":"sql","x":"select u.name, u.roles, c.email, g.name as gym\nfrom users u\njoin credentials c on c.user_id = u.id\njoin gyms g on g.id = u.gym_id;"}],"qa":[{"q":"¿Qué devuelve `JOIN` y qué añade `LEFT JOIN`? ¿Cómo obtienes el último registro por grupo?","a":"`JOIN` solo filas en ambas tablas; `LEFT JOIN` también las de la izquierda sin pareja (null). El último por grupo: `DISTINCT ON`."}]},{"title":"Arrays de Postgres","que":[{"t":"p","x":"`text[]` con `array_append`, `array_remove`, `@>` (contiene), `any()`, `cardinality()`."}],"ejemplo":[{"t":"p","x":"`update users set roles = array_append(roles,'TRAINER')`"}],"qa":[{"q":"¿Cómo preguntas si un array contiene un valor?","a":"`'X' = any(col)` o `col @> array['X']`."}]},{"title":"pg_stat_activity: idle e idle in transaction","que":[{"t":"p","x":"En una conexión `idle` la columna `query` es la ÚLTIMA consulta ejecutada, no una en curso. `idle in transaction` abrió un `BEGIN` y no lo cerró y puede bloquear a otros."}],"ejemplo":[],"qa":[{"q":"En pg_stat_activity, ¿qué ejecuta ahora una conexión `idle` con la columna query llena?","a":"Nada; la query es la última que ejecutó. Ojo con `idle in transaction`, que puede bloquear."}]},{"title":"Cold start vs cache fría","que":[{"t":"p","x":"Arranque en frío del servicio (el compute/contenedor dormido, ~50 s, se quita pagando) no es lo mismo que cache fría (shared_buffers vacío, milisegundos, ocurre siempre; se mitiga con índices y buen diseño de consultas)."}],"ejemplo":[],"qa":[{"q":"¿Qué dos costes se confunden y cuál NO se arregla pagando?","a":"Cold start (se arregla pagando) y cache fría (no; se arregla con índices y diseño de consultas)."}]},{"title":"Migraciones con dbmate","que":[{"t":"p","x":"Archivo SQL versionado con un cambio de estructura, con secciones `-- migrate:up` y `-- migrate:down`, identificado por timestamp en el nombre. dbmate las aplica en orden y registra las aplicadas en `schema_migrations`. Ciclo: `migrate new nombre` → escribir SQL (y probar siempre el `down`) → `db:migrate` → `status` → `rollback`. Una migración que ya llegó a un ambiente compartido no se edita: se escribe otra. Los datos de prueba van con seed, no en migraciones. Equivale a Alembic (`alembic revision`/`upgrade head`, tabla `alembic_version`)."}],"ejemplo":[],"qa":[{"q":"¿Por qué no se edita una migración ya aplicada?","a":"Porque dbmate solo mira el número de versión; las bases que ya la aplicaron nunca verían el cambio, así que se crea otra migración."}]},{"title":"Backup y restore con pg_dump (y ubicación del volumen)","que":[{"t":"p","x":"Un backup real no es copiar el volumen sino `pg_dump -Fc` (consistente): `docker exec ... pg_dump -U gym -Fc gym > gym.dump`; restaurar con `pg_restore` en una base de práctica; `--schema-only` muestra la estructura en SQL. En Windows Docker corre Linux en una VM (WSL2): el volumen vive en `/var/lib/docker/volumes/<nombre>/_data`, dentro de `docker_data.vhdx`; son archivos binarios internos que no se tocan (copiarlos con la base corriendo puede corromperla). En PowerShell no usar `>` (corrompe el binario): usar `docker cp`. Un backup que no se probó no cuenta."}],"ejemplo":[],"qa":[{"q":"¿Cómo se respalda correctamente una base Postgres en Docker y por qué no copiar el volumen?","a":"Con `pg_dump`; copiar el volumen son archivos binarios internos y puede corromper la base."}]},{"title":"DBeaver (cliente SQL gráfico)","que":[{"t":"p","x":"Cliente gráfico que se conecta directo a Postgres (`localhost:5433`, base/usuario/clave `gym`), sin pasar por la API; muestra tablas, datos, `schema_migrations`, joins y diagrama ER. Sirve para mirar y verificar, no para editar datos a mano con la API corriendo (se saltaría validaciones y el hash). Equivalente a pgAdmin/DataGrip/TablePlus."}],"ejemplo":[],"qa":[{"q":"¿Por qué no editar datos en DBeaver mientras corre la API?","a":"Porque salta la lógica de la API (validaciones, hash de contraseña)."}]},{"title":"SQL plano + dbmate vs ORM","que":[{"t":"p","x":"Ventajas del SQL plano: lo escrito es lo que corre, se usan funciones nativas de Postgres (check, índices parciales, triggers), no agrega dependencias, y se aprende SQL transferible. Costos: sin autocompletado de tablas en TS y migraciones escritas a mano. Con ~11 tablas se mantiene bien; un ORM compensa con muchas tablas o equipo mayor."}],"ejemplo":[],"qa":[{"q":"¿Qué se pierde al elegir SQL plano sobre un ORM?","a":"Autocompletado de tablas/columnas y migraciones autogeneradas."}]},{"title":"Pasar de local a una base en línea (mudanza a producción)","que":[{"t":"p","x":"La API solo conoce `DATABASE_URL`: mudarse es cambiarla (`...@host:5432/gym?sslmode=require`). Postgres nunca expuesto a internet (firewall: 22, 80, 443; túnel SSH); SSL cuando sale de la máquina; claves reales y mínimo privilegio, secretos en variables de entorno; las migraciones corren igual en servidor; `pg_dump` → `pg_restore`; backups diarios cifrados fuera del servidor (probar restaurar) y monitoreo. Opciones: VPS propio con Docker + Caddy (HTTPS) o Supabase Free (se pausa tras 7 días sin uso, tope 500 MB)."}],"ejemplo":[],"qa":[{"q":"¿Qué cambia en la API al migrar la base a un servidor?","a":"Solo la variable `DATABASE_URL` (más SSL y credenciales reales)."}]},{"title":"SQLite en desarrollo y PostgreSQL en producción","que":[{"t":"p","x":"Con SQLAlchemy cambiar de motor es cambiar la URL de conexión (`DATABASE_URL`). Los tests usan SQLite en memoria; producción PostgreSQL (driver `psycopg`). Django usa SQLite por defecto."}],"ejemplo":[{"t":"p","x":"`postgresql+psycopg://user:pass@db:5432/notas`"}],"qa":[{"q":"¿Qué cambias para migrar de SQLite a PostgreSQL si la capa de datos está bien montada?","a":"Solo la URL de conexión (y el driver)."}]},{"title":"Persistencia JSON vs base de datos real (race condition)","que":[{"t":"p","x":"Guardar un JSON entero en cada petición es un read-modify-write no atómico: dos peticiones concurrentes se pisan (la última gana) y un fallo a mitad corrompe el archivo. Una BD aporta transacciones, locking, integridad y campos autogenerados. Mezclar ambos almacenes da inconsistencia."}],"ejemplo":[],"qa":[{"q":"¿Qué problema tiene un JSON como base de datos con peticiones concurrentes?","a":"Una condición de carrera: A lee, B lee, A escribe, B escribe encima y se pierde el cambio de A."}]}]},{"title":"Acceso a SQL desde código: parametrización, ORMs y migraciones","concepts":[{"title":"Consultas parametrizadas (anti SQL injection)","que":[{"t":"p","x":"Nunca se concatenan valores al texto SQL: se usan placeholders y los valores van aparte. sqlite3: `?` o `:nombre`; mysql2 (Node): `?` con un array (`db.execute('INSERT ... VALUES (?, ?, ?)', [a,b,c])`; `result.insertId` y `affectedRows` informan el resultado). En sqlite3, `con.row_factory = sqlite3.Row` da acceso por nombre de columna, `executescript` ejecuta varios statements y `executemany` inserta muchos registros. SQLAlchemy ORM + Alembic sirven al migrar a PostgreSQL."}],"ejemplo":[{"t":"p","x":"`con.execute(\"SELECT price FROM prices WHERE product_id=? ORDER BY id DESC LIMIT 1\", (pid,))`"}],"qa":[{"q":"¿Por qué usar `?` y valores aparte en vez de concatenar strings al SQL?","a":"Para evitar inyección SQL: el valor no se concatena en el texto de la consulta."}]},{"title":"Pool de conexiones","que":[{"t":"p","x":"`mysql.createPool({connectionLimit, waitForConnections, queueLimit})` reutiliza conexiones para mejor rendimiento; configuración por variables de entorno (`dotenv`)."}],"ejemplo":[],"qa":[{"q":"¿Qué ventaja tiene un pool de conexiones?","a":"Reutiliza conexiones y mejora el rendimiento."}]},{"title":"ORM Sequelize vs SQL directo","que":[{"t":"p","x":"Sequelize define modelos (`sequelize.define`, `DataTypes`, `allowNull`, `unique`, `timestamps`) y métodos `create`, `findAll({where})`, `update`, `destroy` en lugar de escribir SQL. El SQL directo da control explícito."}],"ejemplo":[],"qa":[{"q":"¿Qué métodos de Sequelize equivalen a INSERT, SELECT, UPDATE y DELETE?","a":"`create`, `findAll`, `update`, `destroy`."}]},{"title":"SQLAlchemy: DeclarativeBase, Mapped y mapped_column","que":[{"t":"p","x":"Declaras tablas como clases que heredan de `Base(DeclarativeBase)`. `Mapped[tipo]` define el tipo Python y `mapped_column()` las propiedades SQL (primary_key, unique, ForeignKey). `Base.metadata` registra tablas para `create_all`."}],"ejemplo":[{"t":"p","x":"`id: Mapped[int] = mapped_column(primary_key=True)`"}],"qa":[{"q":"¿Qué hace `Base.metadata.create_all(engine)`?","a":"Emite `CREATE TABLE IF NOT EXISTS` para todos los modelos registrados (no migra tablas ya existentes)."}]},{"title":"SQLAlchemy: Engine y Session","que":[{"t":"p","x":"`create_engine(URL)` configura la conexión (`echo=True` muestra el SQL). `Session` es la unidad de trabajo: gestiona la conexión, rastrea objetos y agrupa cambios en transacciones."}],"ejemplo":[],"qa":[{"q":"¿Qué es una Session de SQLAlchemy?","a":"La unidad de trabajo que habla con la BD: agrupa consultas y commits en una transacción."}]},{"title":"SQLAlchemy: select(), where(), scalars().all()","que":[{"t":"p","x":"`select(Nota)` construye la consulta sin ejecutarla; `.where(...)` filtra; `session.scalars(...)` la ejecuta y devuelve objetos (no tuplas) y `.all()`/`.first()` materializan el resultado."}],"ejemplo":[{"t":"p","x":"`session.scalars(select(Nota).where(Nota.usuario_id == u.id)).all()`"}],"qa":[{"q":"¿Qué diferencia hay entre `session.execute` y `session.scalars`?","a":"`execute` devuelve filas (tuplas de un elemento); `scalars` devuelve directamente los objetos."}]},{"title":"SQLAlchemy: add / commit / refresh","que":[{"t":"p","x":"`add` registra el objeto, `commit` ejecuta el INSERT y confirma, `refresh` recarga valores generados por la BD (id, fechas). Sin `commit` se descarta; sin `refresh` el id/fechas serían `None`."}],"ejemplo":[],"qa":[{"q":"¿Por qué `session.refresh(nota)` tras el commit?","a":"Para traer los valores que genera la BD (id autoincremental, fechas con server_default) al objeto en memoria."}]},{"title":"server_default y onupdate con func.now()","que":[{"t":"p","x":"`server_default=func.now()` pone la fecha en el motor de BD al insertar; `onupdate=func.now()` la refresca en cada UPDATE. Es la función SQL de la base, no `datetime.now()` de Python."}],"ejemplo":[],"qa":[{"q":"¿Quién calcula la fecha con `server_default=func.now()`?","a":"La base de datos, no Python."}]},{"title":"ForeignKey con ondelete y PRAGMA foreign_keys en SQLite","que":[{"t":"p","x":"`ForeignKey(\"usuarios.id\", ondelete=\"CASCADE\")` borra notas al borrar el usuario. SQLite trae las FK apagadas: hay que ejecutar `PRAGMA foreign_keys=ON` por conexión (`@event.listens_for(Engine, \"connect\")`) o la restricción es solo decorativa."}],"ejemplo":[],"qa":[{"q":"¿Por qué hace falta `PRAGMA foreign_keys=ON` en SQLite?","a":"Porque SQLite desactiva las FK por defecto; sin él no se hacen cumplir."}]},{"title":"Migraciones: Alembic y create_all","que":[{"t":"p","x":"`create_all` solo crea tablas nuevas; si cambias un modelo no altera la tabla existente. Las migraciones versionadas (Alembic) aplican esos cambios."}],"ejemplo":[],"qa":[{"q":"¿Qué limitación tiene `create_all`?","a":"No modifica tablas ya existentes; para eso se usan migraciones (Alembic)."}]},{"title":"Pipeline ETL: leer → limpiar → validar → cargar → reportar","que":[{"t":"p","x":"Flujo de datos sucios: `csv.DictReader` → `limpiar_fila` (strip, minúsculas, coma decimal, dos formatos de fecha, validar positivos, `ValueError`) → `limpiar_filas` devuelve `(validas, rechazadas)` → cargar a SQLite en memoria → consultas de reporte. Se prueba primero la función de limpieza porque todo depende de ella."}],"ejemplo":[],"qa":[{"q":"¿Qué devuelve `limpiar_filas` y por qué?","a":"`(validas, rechazadas)`: así no se pierde información sobre filas descartadas y se puede auditar."}]},{"title":"Coma decimal y formatos de precio","que":[{"t":"p","x":"Normalizar `\"12,50\"` con `replace(\",\", \".\")`. Para precios con miles/decimales mixtos: si ambos separadores existen, el último es el decimal; con solo coma, 2-3 dígitos finales sugieren decimal."}],"ejemplo":[],"qa":[{"q":"¿Cómo conviertes `\"12,50\"` a float?","a":"`float(\"12,50\".replace(\",\", \".\"))`."}]}]},{"title":"HTTP y REST","concepts":[{"title":"HTTP (petición y respuesta)","que":[{"t":"p","x":"Protocolo cliente-servidor. La petición lleva método, path, query params, headers y a veces body; la respuesta lleva status code, headers y body. Cliente en Python: `requests`; servidor: FastAPI (a menudo con `async def` para no bloquearse)."}],"ejemplo":[],"qa":[{"q":"¿Qué contiene una petición y una respuesta HTTP?","a":"Petición: método, path, query params, headers y a veces body. Respuesta: status code, headers y body."}]},{"title":"Headers, autenticación y rate limits","que":[{"t":"p","x":"Metadata de la petición/respuesta (`Content-Type`, `Authorization: Bearer <token>`). Analogía: el sobre; el body es la carta. El servidor lee el sobre antes del contenido (`Content-Type: application/json` indica cómo parsear). Autenticación: API keys, Basic, Bearer, OAuth. Hay que manejar timeouts, reintentos y respetar rate limits."}],"ejemplo":[],"qa":[{"q":"¿Qué papel cumple `Content-Type: application/json` y qué cabecera envía un token JWT?","a":"Dice al servidor que el body es JSON y cómo parsearlo; el token va en `Authorization: Bearer <token>`."}]},{"title":"Body (JSON)","que":[{"t":"p","x":"Parte de la petición/respuesta que transporta datos estructurados en texto JSON; en Python es un dict o lista. Se convierte con `json.dumps()` / `json.loads()`; con `requests` se envía con `json=`."}],"ejemplo":[{"t":"code","lang":"python","x":"respuesta = requests.post(\"https://ejemplo.com\", json={\"usuario\": \"carlos\", \"edad\": 28})\ndatos = respuesta.json()"}],"qa":[{"q":"¿Cómo se pasa un dict a texto JSON y viceversa?","a":"`json.dumps()` a texto y `json.loads()` a objeto Python."}]},{"title":"Query params","que":[{"t":"p","x":"Filtros opcionales pegados a la URL tras `?` (`/productos?categoria=zapatos&precio_max=50`). Se usan con GET porque no lleva body. El path identifica el recurso; el query param lo filtra."}],"ejemplo":[],"qa":[{"q":"¿Diferencia entre path y query param?","a":"El path identifica el recurso; el query param lo filtra."}]},{"title":"Métodos HTTP y semántica REST","que":[{"t":"p","x":"GET lee; POST crea; PUT reemplaza el recurso entero; PATCH modifica parcialmente; DELETE borra. Menos comunes: HEAD (solo headers), OPTIONS (métodos soportados, CORS), TRACE, CONNECT. PATCH no es *path* (la ruta). GET debe ser seguro e idempotente."}],"ejemplo":[],"qa":[{"q":"¿Qué hace cada método GET, POST, PUT, PATCH y DELETE, y diferencia entre PUT y PATCH?","a":"Leer, crear, reemplazar completo, modificar parcial y borrar. PUT reemplaza el recurso completo; PATCH actualiza solo los campos enviados."}]},{"title":"GET","que":[{"t":"p","x":"Lee un recurso sin modificar nada; por convención sin body (filtros en query params/path). Es idempotente y seguro, por eso navegadores y proxies pueden cachearlo."}],"ejemplo":[],"qa":[{"q":"¿Por qué GET es cacheable?","a":"Porque es idempotente y seguro (no cambia el estado del servidor)."}]},{"title":"POST","que":[{"t":"p","x":"Crea algo nuevo enviando datos en el body. No es idempotente: repetirlo suele crear dos recursos. Responde típicamente `201 Created` con el recurso y su `id`."}],"ejemplo":[],"qa":[{"q":"¿Por qué POST no es idempotente?","a":"Mandar el mismo POST dos veces suele crear dos recursos distintos."}]},{"title":"PUT","que":[{"t":"p","x":"Reemplaza un recurso entero con el objeto completo en el body. Es idempotente; los campos que falten suelen quedar vacíos. Para cambios parciales, PATCH."}],"ejemplo":[],"qa":[{"q":"¿Qué pasa si un PUT no incluye todos los campos?","a":"Los faltantes suelen quedar vacíos/reseteados (reemplazo total)."}]},{"title":"PATCH","que":[{"t":"p","x":"Modifica parcialmente enviando solo los campos que cambian; los demás quedan tal cual. Encaja con el patrón `EditarNota` de Pydantic (campos opcionales)."}],"ejemplo":[],"qa":[{"q":"¿Qué pasa con los campos no enviados en un PATCH?","a":"Quedan como estaban."}]},{"title":"DELETE","que":[{"t":"p","x":"Borra un recurso identificado por el path (`/notas/5`), normalmente sin body. Idempotente en la práctica: el estado final es el mismo, aunque la segunda vez suela dar 404."}],"ejemplo":[],"qa":[{"q":"¿Es DELETE idempotente y qué status da la segunda vez?","a":"Sí en la práctica; la segunda vez suele responder 404 en vez de 200/204."}]},{"title":"Idempotencia","que":[{"t":"p","x":"Una operación idempotente produce el mismo estado final aunque se repita: GET, PUT y DELETE lo son; POST normalmente no. En apps offline, un uuid generado en el cliente vuelve idempotente el reintento de un POST."}],"ejemplo":[],"qa":[{"q":"¿Es POST idempotente?","a":"No: repetirlo suele crear recursos duplicados."}]},{"title":"Códigos de estado HTTP (1xx-5xx, 401 vs 403)","que":[{"t":"p","x":"El primer dígito agrupa: 1xx informativo, 2xx éxito (`200` OK, `201` Created, `204` No Content), 3xx redirección, 4xx error del cliente (`400` datos inválidos, `401`, `403`, `404`, `409` conflicto/duplicado, `422` validación Pydantic), 5xx error del servidor (`500`; el detalle se loguea, no se filtra al cliente). 401 = no autenticado (sin/inválida la credencial o credenciales incorrectas); 403 = autenticado pero sin permiso (rol insuficiente o cuenta desactivada). `respuesta.raise_for_status()` lanza excepción ante 4xx/5xx."}],"ejemplo":[],"qa":[{"q":"¿Cuándo devuelves 401, 403 y 404, y qué código indica email ya registrado?","a":"401 sin autenticación válida; 403 autenticado sin permiso; 404 si no existe; 409 para email repetido."}]},{"title":"API REST CRUD con Express","que":[{"t":"p","x":"`POST /profesores` crea (201), `GET` lista activos, `DELETE /:id` baja lógica (UPDATE), `DELETE /:id/fisico` baja física; 404 si `affectedRows === 0`; try/catch con 500; `express.json()` como middleware."}],"ejemplo":[],"qa":[{"q":"¿Qué código HTTP devuelve una creación exitosa y cuál un recurso no encontrado?","a":"201 y 404."}]},{"title":"requests: GET y status_code / .json()","que":[{"t":"p","x":"`requests.get(url)` pide datos a un servidor; `.status_code` indica el resultado (200 = ok) y `.json()` convierte la respuesta JSON en dict de Python."}],"ejemplo":[{"t":"p","x":"`r = requests.get(\"https://api.github.com/users/python\"); r.json()`"}],"qa":[{"q":"¿Qué devuelve `.json()` de una respuesta de requests?","a":"La respuesta convertida a estructuras de Python (dict/list)."}]},{"title":"Reintentos con \"no reintentar si NOT_FOUND\"","que":[{"t":"p","x":"Para llamadas externas que fallan a veces: bucle de hasta `maxIntentos` con `try { return await consultar(id) } catch`; si el error es permanente (`code === 'NOT_FOUND'`) no se reintenta; al agotar intentos se lanza el último error. Validar `maxIntentos` (`RangeError`)."}],"ejemplo":[],"qa":[{"q":"¿Por qué no reintentar un error NOT_FOUND?","a":"Porque reintentar no cambia el resultado; solo conviene con errores transitorios."}]},{"title":"async/await y asyncio.gather","que":[{"t":"p","x":"Con `async def` y `await` se lanzan tareas I/O en paralelo (10 peticiones en ~3 s en vez de 100 s). `asyncio.gather(*tareas, return_exceptions=True)` espera a todas sin que un fallo tumbe el resto."}],"ejemplo":[],"qa":[{"q":"¿Para qué sirve `return_exceptions=True` en `asyncio.gather`?","a":"Para que si una tarea falla no se cancele todo; el error se devuelve como resultado."}]},{"title":"asyncio.Semaphore: limitar concurrencia","que":[{"t":"p","x":"Un `Semaphore(5)` permite como máximo 5 tareas simultáneas (rate limiting); junto con un timeout por petición evita saturar servidores."}],"ejemplo":[],"qa":[{"q":"¿Qué hace `asyncio.Semaphore(5)`?","a":"Limita a 5 las tareas que corren a la vez."}]},{"title":"Web scraping: requests + BeautifulSoup vs Playwright/Selenium","que":[{"t":"p","x":"Dos fases: con `requests` TRAES el HTML y con BeautifulSoup EXTRAES los datos (selectores CSS); luego se guarda en CSV/SQLite. Para HTML estático basta eso; Playwright/Selenium cuando la página se renderiza con JavaScript. Un rastreador empieza como una lista de dicts (tienda, precio, url) recorrida con `for`. Respeta legalidad y términos del sitio."}],"ejemplo":[],"qa":[{"q":"¿Qué hace requests, qué hace BeautifulSoup y cuándo necesitas Playwright?","a":"requests trae el HTML; BeautifulSoup lo parsea para extraer; Playwright cuando el contenido lo genera JavaScript en el navegador."}]}]},{"title":"FastAPI, Pydantic y arquitectura de una API","concepts":[{"title":"FastAPI, Uvicorn y Swagger (/docs)","que":[{"t":"p","x":"FastAPI convierte funciones Python en rutas HTTP (`app = FastAPI()`, decoradores `@app.get(\"/\")`, `@app.post(...)`, rutas con parámetros `/productos/{nombre}`), valida con type hints/Pydantic y genera docs OpenAPI en `/docs` gratis. Uvicorn es el servidor ASGI que escucha el puerto (`uvicorn main:app --reload`)."}],"ejemplo":[],"qa":[{"q":"¿Qué hace Uvicorn, qué hace FastAPI y qué ruta de documentación regala?","a":"FastAPI define qué hacer en cada ruta; Uvicorn es el servidor que recibe las peticiones; la documentación interactiva está en `/docs`."}]},{"title":"Path params, query params y body en FastAPI","que":[{"t":"p","x":"Path: `/notas/{id}`; query: `?skip=0&limit=20`; body: JSON validado con un modelo Pydantic. FastAPI decide por la firma del parámetro."}],"ejemplo":[],"qa":[{"q":"¿Cómo distingue FastAPI un path param de un body?","a":"Por la firma: nombre en la ruta = path; modelo Pydantic = body; valores simples con default = query."}]},{"title":"Pydantic BaseModel: validación de entrada y salida","que":[{"t":"p","x":"Clases que heredan de `BaseModel` declaran la forma de los datos con tipos (`url: HttpUrl`, `price: float | None = None`); validan en runtime y serializan a JSON; FastAPI valida automáticamente la entrada y rechaza con error de validación si un campo tiene tipo incorrecto. Se usan modelos de entrada (`NotaIn`) y de salida (`NotaOut`) separados a propósito. `EmailStr` valida email, `Field(min_length=1)` restricciones."}],"ejemplo":[],"qa":[{"q":"¿Por qué separar `NotaIn` y `NotaOut` y qué hace Pydantic ante un campo de tipo incorrecto?","a":"Entrada y salida son contratos distintos; el de salida decide qué campos se exponen (nunca `hashed_password`). Ante un tipo incorrecto rechaza la petición con error de validación (422)."}]},{"title":"from_attributes y response_model","que":[{"t":"p","x":"`ConfigDict(from_attributes=True)` permite a Pydantic leer atributos de objetos ORM; `NotaOut.model_validate(obj)` convierte. `response_model=NotaOut` o el tipo de retorno filtran/validan la salida y documentan el schema."}],"ejemplo":[],"qa":[{"q":"¿Para qué `from_attributes=True`?","a":"Para construir el modelo Pydantic a partir de un objeto con atributos (ORM) en vez de un dict."}]},{"title":"Inyección de dependencias con Depends y Annotated","que":[{"t":"p","x":"`Depends(func)` hace que FastAPI ejecute `func` antes de la ruta y entregue su resultado. `SessionDep = Annotated[Session, Depends(get_session)]` es un alias reutilizable. Sin `Depends`, FastAPI trataría `session` como parte del body y daría 422."}],"ejemplo":[],"qa":[{"q":"¿Qué ventaja da `Depends(get_session)`?","a":"Cada ruta recibe una sesión ya abierta y cerrada automáticamente, sin repetir código ni arriesgar fugas."}]},{"title":"Dependencia con yield (setup/teardown por petición)","que":[{"t":"p","x":"`get_session` hace `with Session(...) as s: yield s`: lo previo al `yield` es setup, lo posterior (cierre del `with`) corre tras la respuesta aunque haya excepción. Una sesión nueva por petición, nunca global."}],"ejemplo":[],"qa":[{"q":"¿Qué pasaría si `get_session` usara `return` en vez de `yield`?","a":"Nadie cerraría la sesión: fuga de conexiones."}]},{"title":"Errores HTTP controlados: HTTPException y manejo centralizado","que":[{"t":"p","x":"FastAPI: `raise HTTPException(status_code=404, detail=\"...\")` corta la ruta y arma la respuesta JSON de error en vez de tumbar el servidor; devolver un dict de error con 200 es semánticamente incorrecto. Hono (GYM): `fail(status, message)` lanza una `HTTPException` y `app.onError` la convierte en `{error: mensaje}` con su status; cualquier otro error se loguea y responde 500 genérico sin filtrar detalles. Códigos usados: 400, 401, 403, 404, 409."}],"ejemplo":[],"qa":[{"q":"¿Por qué lanzar `HTTPException` y no devolver `{\"error\": ...}`, y qué hace `app.onError` con un error no controlado?","a":"Para que el código HTTP sea correcto (200 con error rompe a los clientes). `onError` lo loguea y responde 500 `{error: \"error interno\"}` sin exponer detalles."}]},{"title":"APIRouter con prefix y tags","que":[{"t":"p","x":"Cada dominio (`/auth`, `/notas`) vive en su `APIRouter(prefix=..., tags=[...])` y se registra con `app.include_router(...)`, manteniendo `main.py` pequeño."}],"ejemplo":[],"qa":[{"q":"¿Para qué sirve `APIRouter`?","a":"Para modularizar rutas por dominio y montarlas en la app con `include_router`."}]},{"title":"PATCH parcial y paginación skip/limit","que":[{"t":"p","x":"Con campos `str | None = None` el cliente envía solo lo que cambia; en el servidor se actualiza solo lo que no sea `None`. La lista paginada usa `.offset(skip).limit(limit)` y devuelve solo metadatos (sin contenido)."}],"ejemplo":[],"qa":[{"q":"¿Cómo implementas una edición parcial?","a":"Campos opcionales en el modelo y `if datos.campo is not None:` antes de asignar."}]},{"title":"Arquitectura en capas: routers / services / repositories","que":[{"t":"p","x":"Separar rutas (HTTP), servicios (lógica de negocio) y repositorios (acceso a BD) y modelos/schemas. Facilita pruebas y cambios de BD."}],"ejemplo":[],"qa":[{"q":"¿Qué responsabilidad tiene cada capa?","a":"Router = HTTP; service = reglas de negocio; repository = consultas a la BD."}]},{"title":"Endpoint /health","que":[{"t":"p","x":"Ruta mínima que devuelve `{\"status\": \"ok\"}` para comprobar que el servicio vive (monitoreo/orquestadores). En GYM además comprueba que la BD responda."}],"ejemplo":[],"qa":[{"q":"¿Para qué un endpoint `/health`?","a":"Para que monitoreo o contenedores comprueben que la app responde."}]},{"title":"Servir el frontend desde FastAPI y proxy de Vite","que":[{"t":"p","x":"En producción `app.mount(\"/\", StaticFiles(directory=\"static\", html=True))` sirve el build de React; en desarrollo Vite (`:5173`) hace proxy de `/auth` y `/notas` al backend (`:8000`) para usar rutas relativas igual que en producción (sin CORS). Si el frontend va separado se configura CORS."}],"ejemplo":[],"qa":[{"q":"¿Qué resuelve el `server.proxy` de Vite?","a":"Que el frontend use rutas relativas en dev reenviándolas al backend, evitando problemas de CORS."}]}]},{"title":"Autenticación, autorización y seguridad de APIs","concepts":[{"title":"Hash de contraseñas vs encriptación (bcrypt, argon2)","que":[{"t":"p","x":"Una contraseña nunca se guarda en texto plano ni cifrada reversible: se guarda su hash con sal (bcrypt `$2b$...`; argon2id `$argon2id$...` con `@node-rs/argon2`, en `credentials.password_hash`). El hash es de un solo sentido; al login se compara (`bcrypt.checkpw`, `verifyPassword`). En sign-in GYM se verifica incluso si el usuario no existe, para no filtrar por tiempo de respuesta si el email existe."}],"ejemplo":[{"t":"p","x":"`bcrypt.hashpw(pw.encode(), bcrypt.gensalt())`"}],"qa":[{"q":"¿Diferencia entre hash y encriptación, y por qué verificar la clave aunque el usuario no exista?","a":"El hash es irreversible; la encriptación se puede descifrar con la clave. Verificar siempre evita revelar por tiempo de respuesta si el email está registrado."}]},{"title":"JWT: estructura, claims, firma y expiración","que":[{"t":"p","x":"Token `encabezado.datos.firma`: credencial firmada que la app guarda y manda en cada petición (`Authorization: Bearer <token>`); la API la verifica sin pedir la clave de nuevo. Lleva `sub` (id de usuario) y `exp`; se firma con un secreto (HS256). El servidor valida firma y expiración en cada petición con `jwt.decode`; un token manipulado o expirado da 401. En GYM `issueToken` firma `{sub, exp}` con `JWT_SECRET`, vence en 30 días y el secret por defecto `local-dev-only` solo vale en desarrollo."}],"ejemplo":[],"qa":[{"q":"¿Qué lleva dentro un JWT, qué comprueba el servidor y cuánto dura el del proyecto GYM?","a":"Claims como `sub` y `exp`; el servidor verifica firma y expiración. En GYM: HS256, 30 días."}]},{"title":"Proteger rutas: HTTPBearer/get_current_user y middlewares requireAuth → requireRole","que":[{"t":"p","x":"FastAPI: una dependencia lee `Authorization: Bearer <token>`, decodifica, busca el usuario y lo devuelve (401 si falla); la ruta protegida declara `usuario: UsuarioActual`. Hono (GYM): cadena `requireAuth` (verifica el JWT y vuelve a consultar la BD del usuario `where active`) → `requireRole(...roles)` (fábrica que revisa roles de `c.get('user')`) → handler SQL. Releer la BD hace que desactivar a un usuario corte el acceso al instante aunque su token siga vigente 30 días."}],"ejemplo":[],"qa":[{"q":"¿Cómo proteges un endpoint con login y por qué `requireAuth` consulta la BD aunque el JWT sea válido?","a":"Con una dependencia/middleware que valida el token y retorna el usuario actual; la consulta a la BD corta al instante a usuarios desactivados o borrados."}]},{"title":"Flujo de sign-up y sign-in (mismo mensaje de error)","que":[{"t":"p","x":"Sign-up GYM: validar (consent, nombre, email, clave >= 8) → buscar gym por `access_code` (400) → email duplicado (409, `IntegrityError` + `rollback` en FastAPI) → hash → transacción que inserta `users` (MEMBER) y `credentials` → JWT → 201 `{token}` → `signIn(token)` → `/me`. Sign-in: 401 si clave incorrecta (\"Credenciales inválidas\", idéntico si el email no existe) y 403 si la cuenta está desactivada. La respuesta idéntica evita enumerar emails y dar pistas al atacante."}],"ejemplo":[],"qa":[{"q":"¿401 o 403 para clave incorrecta y para cuenta desactivada, y por qué el mismo mensaje si falla email o clave?","a":"Clave incorrecta: 401; clave correcta pero cuenta inactiva: 403. El mismo mensaje no revela qué cuentas existen."}]},{"title":"Autorización por propietario/tenant: 404 vs 403","que":[{"t":"p","x":"Cada ruta recibe el usuario actual y filtra/valida: nota inexistente → 404; existe pero es de otro → 403; el listado filtra `usuario_id == usuario.id`; el `usuario_id` sale del token, nunca del body. En GYM (multi-tenant) se busca siempre con `gym_id` del autenticado (`findUserInGym`) y se responde 404 también si el id es de otro gimnasio o no es UUID válido, para no confirmar que existe."}],"ejemplo":[],"qa":[{"q":"Un usuario pide el recurso de otro: ¿403 o 404, y por qué el proyecto GYM elige 404?","a":"403 si se quiere decir \"existe pero no es tuyo\"; GYM usa 404 para no revelar que existe en otro tenant."}]},{"title":"Secretos y variables de entorno (JWT_SECRET)","que":[{"t":"p","x":"La clave secreta y la URL de BD van en `.env`/variables inyectadas, nunca en el código ni en la imagen Docker; el compose puede exigirla (`${JWT_SECRET:?falta}`)."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas hornear secretos en una imagen?","a":"Inyectándolos como variables de entorno desde `.env`/compose en tiempo de ejecución."}]},{"title":"pydantic-settings: configuración validada","que":[{"t":"p","x":"Una clase `Settings(BaseSettings)` lee `.env`, valida tipos al arrancar (falla rápido si falta un token) y permite configuraciones distintas para test (`:memory:`)."}],"ejemplo":[],"qa":[{"q":"¿Qué ventaja tiene `BaseSettings` sobre `os.getenv` disperso?","a":"Centraliza y valida la configuración al inicio con tipos, fallando rápido si falta algo."}]},{"title":"XSS y renderizado seguro de Markdown","que":[{"t":"p","x":"`react-markdown` por defecto no renderiza HTML incrustado (seguro). Si habilitas HTML crudo, DOMPurify es obligatorio. Prueba: nota con `<script>` o `<img onerror>` no debe ejecutar nada."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas XSS al mostrar Markdown de usuarios?","a":"No renderizando HTML crudo (react-markdown por defecto) o sanitizándolo con DOMPurify."}]},{"title":"Rate limiting, API keys y CORS (hardening)","que":[{"t":"p","x":"Limitar peticiones por IP (slowapi), exigir API key a endpoints sensibles, configurar CORS e input sanitization antes de exponer una API a internet."}],"ejemplo":[],"qa":[{"q":"¿Qué protege el rate limiting?","a":"Evita abuso/fuerza bruta limitando peticiones por cliente en una ventana de tiempo."}]},{"title":"Sanitizar URLs de tracking","que":[{"t":"p","x":"Antes de guardar una URL se elimina la query si solo contiene parámetros de tracking (`utm_*`, `gclid`, `fbclid`...) usando `urlparse`, `parse_qs`, `_replace` y `urlunparse`; también se valida que empiece por http(s)."}],"ejemplo":[],"qa":[{"q":"¿Por qué limpiar parámetros utm antes de guardar una URL?","a":"Para que la misma página no se registre como URLs distintas (duplicados) por parámetros de seguimiento."}]}]},{"title":"Django (curso teach-django)","concepts":[{"title":"Django: framework web en Python","que":[{"t":"p","x":"Una caja de herramientas en Python para construir páginas web que leen datos, usan bases de datos y responden formularios. Sigues en Python, solo cambias de territorio."}],"ejemplo":[],"qa":[{"q":"¿Qué es Django?","a":"Un framework de Python para construir aplicaciones web."}]},{"title":"django-admin vs manage.py","que":[{"t":"p","x":"`django-admin` es el comando global, solo para crear el proyecto (`startproject`). `manage.py` vive dentro del proyecto, conoce settings y se usa para todo lo demás (`runserver`, `startapp`, `migrate`)."}],"ejemplo":[],"qa":[{"q":"¿Cuál es la diferencia práctica entre django-admin y manage.py?","a":"django-admin solo crea el proyecto; manage.py, que conoce tu configuración, ejecuta todo lo demás."}]},{"title":"runserver, localhost y puerto","que":[{"t":"p","x":"`python manage.py runserver` arranca el servidor de desarrollo en `127.0.0.1:8000` (localhost; 8000 es el puerto). Se detiene con Ctrl+C y detecta cambios solo. Un `200` en consola indica respuesta exitosa."}],"ejemplo":[],"qa":[{"q":"¿Qué es 127.0.0.1:8000 y qué significa un 200?","a":"Tu propia máquina (localhost) en el puerto 8000; 200 = el servidor respondió correctamente."}]},{"title":"Proyecto vs app en Django","que":[{"t":"p","x":"El proyecto es el contenedor general (`ferreweb`); las apps (`startapp catalogo`) son módulos con funcionalidad concreta. Una app debe registrarse en `INSTALLED_APPS`. `settings.py` define también `MIDDLEWARE` y `DATABASES`; el admin viene incluido."}],"ejemplo":[],"qa":[{"q":"¿Por qué hay que añadir la app a `INSTALLED_APPS`?","a":"Porque Django solo busca templates y otros recursos en apps registradas."}]},{"title":"Django: URL → vista → respuesta","que":[{"t":"p","x":"El navegador manda una petición; Django busca en `urls.py` la ruta (`path('', views.inicio)`), llama a la vista (función Python que recibe `request`) y devuelve un `HttpResponse`. Flujo: navegador → urls.py → views.py → HttpResponse."}],"ejemplo":[],"qa":[{"q":"¿Cuál es el flujo básico de Django y qué archivo decide qué URL llama a qué función?","a":"URL → vista → respuesta; `urls.py` (con `urlpatterns` y `path(...)`) enruta a la vista que devuelve un `HttpResponse`."}]},{"title":"urlpatterns: gana el primer path que coincide","que":[{"t":"p","x":"Django recorre `urlpatterns` de arriba abajo y usa el primero que coincide; el segundo con la misma URL nunca se ejecuta y no avisa (código muerto silencioso)."}],"ejemplo":[],"qa":[{"q":"¿Qué pasa si dos `path` tienen la misma URL?","a":"Se usa el primero; el segundo nunca se ejecuta y no hay aviso."}]},{"title":"Templates y render()","que":[{"t":"p","x":"Un template es un `.html` separado que Django rellena con datos. `render(request, \"catalogo/inicio.html\", contexto)` recibe petición, nombre del template y dict de contexto. Separa HTML de Python."}],"ejemplo":[],"qa":[{"q":"¿Cuáles son los tres argumentos de `render()`?","a":"El request, la ruta del template y el diccionario de contexto."}]},{"title":"Carpeta de templates con namespace (catalogo/templates/catalogo/)","que":[{"t":"p","x":"La carpeta de la app aparece dos veces para evitar colisiones: si dos apps tienen `inicio.html`, el espacio de nombres indica de cuál es cada una. Funciona con `APP_DIRS: True`."}],"ejemplo":[],"qa":[{"q":"¿Por qué `catalogo/templates/catalogo/` y no solo `catalogo/templates/`?","a":"Para namespacing: evita colisiones entre templates con el mismo nombre en distintas apps."}]},{"title":"Variables y lógica en templates ({{ }} y {% if %})","que":[{"t":"p","x":"`{{ nombre }}` inserta un valor; si no está en el contexto queda vacío SIN error (bug silencioso). `{% if contenido %}...{% else %}...{% endif %}` pone lógica en el HTML; `<pre>` respeta los saltos de línea."}],"ejemplo":[],"qa":[{"q":"¿Qué aparece si usas `{{ apellido }}` y no lo pasas en el contexto?","a":"Nada: cadena vacía, sin error ni aviso."}]},{"title":"utils.py: sacar la lógica de la vista","que":[{"t":"p","x":"Por convención en Django, el código que no es vista ni modelo (funciones auxiliares como `leer_contenido`) vive en `utils.py`, y la vista lo importa con `from .utils import ...`."}],"ejemplo":[],"qa":[{"q":"¿Dónde pones por convención una función auxiliar que no es vista ni modelo?","a":"En `utils.py` de la app."}]},{"title":"GET vs POST en una vista Django","que":[{"t":"p","x":"GET pide algo (cargar la página); POST envía algo (formulario/archivo). La misma vista atiende ambos y se distingue con `request.method == \"POST\"`."}],"ejemplo":[],"qa":[{"q":"¿Cómo distingue una vista una visita normal de un envío de formulario?","a":"Mirando `request.method` (`\"GET\"` o `\"POST\"`)."}]},{"title":"Formulario de subida: csrf_token, enctype y request.FILES","que":[{"t":"p","x":"`<form method=\"post\" enctype=\"multipart/form-data\">` con `{% csrf_token %}` (obligatorio: sin él Django responde 403; lo protege `CsrfViewMiddleware`) y un `<input type=\"file\" name=\"archivo\">`. El archivo llega en `request.FILES[\"archivo\"]`, no en `request.POST`; sin `enctype` el archivo llega vacío."}],"ejemplo":[],"qa":[{"q":"¿Dónde vive el archivo subido en la vista y qué atributo del form es imprescindible?","a":"En `request.FILES[\"archivo\"]`; el form necesita `enctype=\"multipart/form-data\"`."}]},{"title":"Vista que empieza con contenido vacío","que":[{"t":"p","x":"Patrón: `contenido = None`; solo si es POST y viene archivo se procesa; al final siempre `render(...)`. Así enviar sin archivo no explota."}],"ejemplo":[],"qa":[{"q":"¿Por qué se inicia `contenido = None` antes del `if request.method == \"POST\"`?","a":"Para que la vista siempre tenga un valor que pasar al template, incluso en GET o sin archivo."}]},{"title":"Migraciones y base de datos en Django (SQLite por defecto)","que":[{"t":"p","x":"Django usa SQLite por defecto (`db.sqlite3`); el aviso \"18 unapplied migrations\" indica migraciones del sistema pendientes de aplicar con `migrate`."}],"ejemplo":[],"qa":[{"q":"¿Qué base de datos usa Django por defecto en un proyecto nuevo?","a":"SQLite (archivo `db.sqlite3`)."}]},{"title":"Django: seguridad de settings (SECRET_KEY y DEBUG)","que":[{"t":"p","x":"`SECRET_KEY` insegura y `DEBUG = True` son solo para desarrollo; en producción van por entorno, `DEBUG=False` y `ALLOWED_HOSTS` definido. `CsrfViewMiddleware` protege formularios."}],"ejemplo":[],"qa":[{"q":"¿Qué dos ajustes de Django nunca van así en producción?","a":"`DEBUG = True` y una `SECRET_KEY` insegura/hardcodeada."}]}]},{"title":"Docker, despliegue y herramientas de proyecto","concepts":[{"title":"Docker: imagen, contenedor y volumen","que":[{"t":"p","x":"Imagen = molde de solo lectura (`postgres:17`, como un `.whl` ya instalado); contenedor = instancia en ejecución, aislada pero compartiendo el kernel (como un proceso en un venv); volumen = directorio gestionado por Docker que sobrevive al contenedor (como dejar los datos fuera del venv). Docker Compose describe varios contenedores en un YAML y los levanta juntos. Un `Dockerfile` (multi-stage) empaqueta la app; `docker build -t myapp .` y `docker-compose up -d`."}],"ejemplo":[],"qa":[{"q":"¿Qué sobrevive si borras un contenedor: la imagen o el volumen, y qué comando borra el volumen?","a":"El volumen conserva los datos; la imagen es solo el molde. El volumen se borra con `docker compose down -v` (y `db:reset`)."}]},{"title":"Dockerfile multi-stage","que":[{"t":"p","x":"Una etapa compila el frontend (`FROM node:20-alpine AS build`) y otra, final, construye el backend Python y copia el resultado (`COPY --from=build /app/dist ./static`). La imagen final queda ligera sin Node."}],"ejemplo":[],"qa":[{"q":"¿Ventaja de un build multi-stage?","a":"La imagen final solo contiene lo necesario para ejecutar (sin herramientas de compilación), más pequeña y segura."}]},{"title":"Orden de capas y caché en Dockerfile","que":[{"t":"p","x":"Copiar primero `requirements.txt`/`package*.json` e instalar, y luego el código, para reutilizar la caché de capas. `pip install --no-cache-dir`. `.dockerignore` excluye `node_modules`, `.venv`, `__pycache__`, `*.db`, `.git`."}],"ejemplo":[],"qa":[{"q":"¿Por qué copiar `requirements.txt` antes que el resto del código?","a":"Para que la capa de dependencias se reutilice de caché si solo cambia el código."}]},{"title":"CMD en forma exec vs shell","que":[{"t":"p","x":"Forma exec `CMD [\"uvicorn\",\"main:app\",\"--host\",\"0.0.0.0\",\"--port\",\"8000\"]` (preferida, el proceso recibe señales). Forma shell expande variables como `${PORT:-8000}` (necesaria para plataformas como Render que inyectan `$PORT`)."}],"ejemplo":[],"qa":[{"q":"¿Cuándo usar la forma shell de CMD?","a":"Cuando necesitas expandir variables de entorno como `$PORT`."}]},{"title":"docker-compose: servicios, healthcheck, depends_on, volúmenes y profiles","que":[{"t":"p","x":"Orquesta servicios (`db` postgres, `backend`, `frontend`, o `migrate` con dbmate). `healthcheck` (`pg_isready`, cada 2 s) + `depends_on: condition: service_healthy` espera a que la BD esté lista, no solo a que exista el contenedor; un volumen nombrado (`db-data:/var/lib/postgresql/data`) persiste datos; `ports` mapea host:contenedor (`127.0.0.1:5433:5432` limita a la máquina local); dentro de la red compose el host de la BD es el nombre del servicio (`db`); `profiles: [tools]` hace que un servicio (p. ej. `migrate`, contenedor de un solo uso que monta `./db:/db`) no arranque con un `up` normal, solo al invocarlo con `run --rm`. `docker-compose up` levanta todo con una orden."}],"ejemplo":[],"qa":[{"q":"¿Cómo evitas que el backend arranque antes que Postgres esté listo y para qué sirve `profiles`?","a":"`healthcheck` en `db` + `depends_on` con `condition: service_healthy`. `profiles` evita que el servicio se levante con `up` normal; solo corre al invocarlo explícitamente."}]},{"title":"Scripts docker del proyecto: db:up, db:migrate y db:reset","que":[{"t":"p","x":"`db:up` = `docker compose up -d db` (`-d` = segundo plano, detached). `db:migrate` = `docker compose run --rm migrate up` (contenedor temporal que aplica migraciones pendientes; `--rm` lo elimina al terminar). `db:reset` = `down -v` + `up -d db` + `migrate up`: borra el volumen y todos los datos, deja la estructura. Puerto 5433 evita chocar con un Postgres local en 5432. Solo lectura: `docker compose ps` y `logs db`. Servicios en redes internas se llaman por nombre (`db:5432`)."}],"ejemplo":[],"qa":[{"q":"¿Qué borra `npm run db:reset` y qué hace `--rm`?","a":"El volumen `db-data` (todas las filas; la estructura se recrea migrando). `--rm` elimina el contenedor temporal al terminar."}]},{"title":"Git, .gitignore y entornos virtuales","que":[{"t":"p","x":"`venv` aísla dependencias; `.gitignore` excluye `.env`, `.venv/`, `__pycache__/`, `*.db`, `node_modules`. Comandos base: init, add, commit, branch, merge, push; commits pequeños por ejercicio."}],"ejemplo":[],"qa":[{"q":"¿Qué hacen `commit`, `branch` y `merge`?","a":"commit guarda un cambio; branch crea una línea paralela; merge integra ramas (los conflictos se resuelven a mano)."}]},{"title":"CI/CD con GitHub Actions","que":[{"t":"p","x":"Workflow YAML en `.github/workflows` que en cada push/PR instala dependencias, corre `pytest --cov`, lint (ruff/black/mypy) y opcionalmente construye/publica la imagen."}],"ejemplo":[],"qa":[{"q":"¿Qué automatiza un workflow de tests en CI?","a":"Ejecutar tests y linters en cada push/PR para detectar roturas antes de integrar."}]},{"title":"Despliegue y producción","que":[{"t":"p","x":"Variables de entorno sin secretos en código, servidores de producción (Gunicorn/Uvicorn), PostgreSQL gestionado, logs, dominio + HTTPS, Nginx reverse proxy, `requirements.txt` vs Poetry vs uv."}],"ejemplo":[],"qa":[{"q":"¿Qué hace un reverse proxy como Nginx?","a":"Recibe el tráfico público (con SSL) y lo reenvía a la app interna."}]},{"title":"Túneles de Cloudflare para demos","que":[{"t":"p","x":"Dos túneles rápidos (`cloudflared tunnel --url http://localhost:3000` y `:8081`) dan URL pública al backend y a Metro; las direcciones cambian cada vez, hay que actualizar `.env` y `EXPO_PACKAGER_PROXY_URL`. Mientras estén abiertos, el backend está en internet."}],"ejemplo":[],"qa":[{"q":"¿Por qué hacen falta dos túneles?","a":"Por cada uno viaja algo distinto: el código de la app (Metro 8081) y las peticiones de la API (3000)."}]},{"title":"Tareas en segundo plano: Celery + Redis, Beat y cron","que":[{"t":"p","x":"Celery ejecuta trabajos fuera del request (worker) sin bloquear la API y Beat programa tareas periódicas (`crontab(hour=\"*/6\")`) con Redis como broker/cola de mensajes. Flower es su dashboard. Alternativas: cron / Task Scheduler."}],"ejemplo":[],"qa":[{"q":"¿Qué papel tiene Redis en Celery?","a":"Es el broker/cola de mensajes por donde se encolan las tareas."}]},{"title":"Observabilidad: logging estructurado, Sentry, Prometheus","que":[{"t":"p","x":"structlog genera logs con campos clave=valor (JSON en producción); Sentry captura errores; Prometheus expone métricas (Counter/Histogram); alertar si % de fallos supera un umbral."}],"ejemplo":[],"qa":[{"q":"¿Ventaja del logging estructurado?","a":"Logs parseables por máquina (JSON) con contexto, fáciles de buscar y agregar."}]},{"title":"Herramientas de calidad: ruff, black, mypy y PEP 8","que":[{"t":"p","x":"PEP 8 estilo oficial; `black`/`ruff` formatean/lintean; `mypy` revisa type hints; DRY/KISS/YAGNI como principios; README con qué hace, cómo correrlo y decisiones."}],"ejemplo":[],"qa":[{"q":"¿Qué significan DRY, KISS y YAGNI?","a":"No te repitas; mantenlo simple; no construyas lo que aún no necesitas."}]}]},{"title":"Proyecto GYM: app móvil, API, base de datos y Docker","concepts":[{"title":"Arquitectura de 3 cajas (app, API, base de datos)","que":[{"t":"p","x":"La app móvil (iPhone, Expo Go) habla por HTTP/JSON con una API (Node + Hono, puerto 3000) que es la única que toca la base Postgres en Docker (puerto 5433). La app nunca habla con la base; mudar la base no toca la app. Todo corre en local; el iPhone usa la IP de la PC en la misma red Wi-Fi (no `localhost`, que sería el propio teléfono)."}],"ejemplo":[],"qa":[{"q":"¿Por qué la app usa la IP de la PC y no `localhost` para llamar a la API?","a":"Porque `localhost` en el iPhone sería el propio teléfono; hay que usar la IP de la PC en la misma red Wi-Fi."}]},{"title":"Puertos del proyecto","que":[{"t":"p","x":"8081 = Metro (Expo, llamado por Expo Go vía QR); 3000 = API Hono; 5433 = Postgres publicado en la PC (mapeado al 5432 del contenedor; se usa 5433 para no chocar con un Postgres local en 5432); 5432 interno = Postgres dentro de la red de Docker (lo usa dbmate como `db:5432`)."}],"ejemplo":[],"qa":[{"q":"¿Por qué dbmate usa `db:5432` y la API `localhost:5433`?","a":"dbmate corre dentro de la red interna de Docker (host `db`, puerto real 5432); la API corre en la PC y usa el puerto publicado 5433 (5432 suele estar ocupado por un Postgres local)."}]},{"title":"Decisión de stack: de Supabase/Kotlin a Postgres propio + Hono + React Native","que":[{"t":"p","x":"El prototipo (Kotlin + Compose + Supabase con RLS) pasó a RN/Expo + Postgres + API Hono por costo recurrente (Supabase Pro ~USD 25/mes) y por querer iOS y Android con un solo código (nativo solo Android obliga a duplicar la app). La seguridad pasó de RLS en la base a chequeos en la API (`requireAuth`, `requireRole`, `findUserInGym`) y `auth.users` pasó a la tabla `credentials`. Se conservó el modelo de datos. Una historia solo es Done con merge."}],"ejemplo":[],"qa":[{"q":"¿Qué reemplazó a RLS al abandonar Supabase?","a":"Chequeos de rol y gimnasio en la API (middlewares), no en la BD."}]},{"title":"Equivalencias Node/TS con Python","que":[{"t":"p","x":"Hono = FastAPI/Flask; postgres.js = psycopg; dbmate = Alembic con SQL puro; argon2 = `argon2-cffi`; hono/jwt = PyJWT; `node --watch` = `uvicorn --reload`; `node --test` = pytest; npm + package.json = pip + pyproject; `node_modules/` = `.venv/`; `useState` = variable que al cambiar redibuja la pantalla."}],"ejemplo":[],"qa":[{"q":"¿Cuál es el equivalente en Python de `node --watch`?","a":"`uvicorn --reload`."}]},{"title":"React Native, Expo, Expo Go y Metro","que":[{"t":"p","x":"React Native escribe JS/TS que dibuja componentes nativos iOS/Android con una sola base de código. Expo es el kit alrededor (CLI, librerías nativas, app Expo Go). Metro es el bundler: junta los `.tsx` en un solo JS y lo sirve al teléfono (puerto 8081). Expo Go ejecuta ese JS sin compilar una app propia. `npx expo start` muestra un QR que se escanea con la cámara de iOS. Las variables `EXPO_PUBLIC_*` se leen al arrancar Metro: hay que reiniciar para que un cambio de `.env` se vea."}],"ejemplo":[],"qa":[{"q":"¿Qué hace Metro y por qué cambiar `.env` no se refleja en caliente?","a":"Es el bundler que junta el código en un JS y lo sirve al teléfono (Expo Go) por el 8081; las `EXPO_PUBLIC_*` se leen al iniciar Metro."}]},{"title":"expo-router y Stack.Protected","que":[{"t":"p","x":"Navegación por archivos: cada archivo de `src/app/` es una pantalla. `_layout.tsx` envuelve todo en `SessionProvider` y usa `Stack.Protected guard={!!me}` para montar solo las pantallas del grupo activo (privadas con sesión, públicas sin ella), sin `if` manual en cada pantalla. `loading` muestra un spinner hasta saber si hay sesión."}],"ejemplo":[],"qa":[{"q":"¿Cómo protege rutas expo-router?","a":"Con `Stack.Protected guard=...`, que solo monta el grupo de pantallas cuyo guard es verdadero."}]},{"title":"Sesión en la app (contexto + SecureStore)","que":[{"t":"p","x":"`session.tsx` es un contexto React con `loading`, `token`, `me`. `signIn(token)` pide `/me` y, si responde bien, guarda el token en `expo-secure-store` (Keychain de iOS, cifrado). Al abrir la app un `useEffect` lee el token guardado; ante 401 (vencido/desactivado) hace `signOut()`; ante falta de red no borra el token (se conserva para reintentar). `useSession()` falla fuera del provider."}],"ejemplo":[],"qa":[{"q":"¿Dónde se guarda el token JWT en el teléfono y cuándo se borra?","a":"En `expo-secure-store` (Keychain cifrado de iOS); se borra cuando la API responde 401, no por falta de red."}]},{"title":"api.ts: wrapper de fetch y ApiError","que":[{"t":"p","x":"Única puerta hacia el backend. Lee `EXPO_PUBLIC_API_URL` del `.env`, agrega `Content-Type: application/json` y `Authorization: Bearer <token>`, y traduce errores: sin red lanza `ApiError` con status 0 y mensaje en español; `204` devuelve `undefined`; si `!response.ok` lanza `ApiError` con el `error` del backend."}],"ejemplo":[],"qa":[{"q":"¿Qué status tiene `ApiError` si fetch falla sin respuesta?","a":"0."}]},{"title":"Offline-first: caché y cola outbox","que":[{"t":"p","x":"El entrenamiento vive en el teléfono; al terminar la sesión entra en una cola (`outbox`) y se sube con `POST` cuando hay señal. El id (uuid) generado en el teléfono hace idempotente el reintento. Un caché local guarda la semana para usar sin conexión."}],"ejemplo":[],"qa":[{"q":"¿Cómo se evita duplicar una sesión al reintentar?","a":"La sesión lleva un uuid generado en el teléfono."}]},{"title":"Hono, node-server y TypeScript sin compilar","que":[{"t":"p","x":"Hono es el framework web (rutas y middlewares); `@hono/node-server` lo adapta al HTTP de Node (puerto `PORT`, 3000). Node >= 22/24 ejecuta `.ts` directo (type stripping): borra anotaciones y corre el JS, sin `tsc`; por eso los imports llevan `.ts` y se evitan los `enum` (generan código real). `npm run dev` usa `node --watch`; `node --test` corre tests."}],"ejemplo":[],"qa":[{"q":"¿Por qué el backend evita `enum` de TypeScript?","a":"Porque el type stripping solo borra anotaciones, y los enum generan código real."}]},{"title":"Rutas de la API y reglas de roles","que":[{"t":"p","x":"`GET /health` (¿API y BD responden?), `POST /auth/sign-up` (público, siempre crea MEMBER, 201 token), `POST /auth/sign-in`, `GET /me`, `DELETE /me` (borrado real, requisito de Google Play, en cascada), `PUT /users/:id/roles` (ADMIN; no puede quitarse su propio rol de ADMIN), `PUT /users/:id/active` (TRAINER/ADMIN; no puede auto-desactivarse). El código de acceso del gym prueba membresía, no privilegios; el ADMIN solo se crea con `seed-admin`."}],"ejemplo":[],"qa":[{"q":"¿Cómo se crea el primer ADMIN si el registro público siempre crea MEMBER?","a":"Con el script `npm run seed:admin` desde la terminal."}]},{"title":"Transacción en la API: registro con sql.begin","que":[{"t":"p","x":"`sql.begin(async tx => ...)` agrupa inserts (`users` + `credentials`) de modo atómico: si algo falla no queda un usuario sin credencial ni viceversa. Equivale a `with conn.transaction():` en psycopg3. El registro público siempre crea MEMBER; el primer admin solo por script `seed:admin`."}],"ejemplo":[],"qa":[{"q":"¿Qué garantiza una transacción en el sign-up?","a":"Que se inserten ambas filas o ninguna."}]},{"title":"Tests de integración de la API contra BD real","que":[{"t":"p","x":"Corren con `node --test` contra la base local real (sin mocks); cada test usa datos únicos (`TEST-<uuid>`, `accessCode` único) para no chocar con otros tests ni datos, y `before/after` crean y borran datos. Cubren: sign-up válido, código inválido, sin consentimiento, `roles: ['ADMIN']` ignorado, email duplicado sin importar mayúsculas (409), clave incorrecta (401), permisos por rol (403), desactivar corta el acceso sin borrar historial, borrar cuenta en cascada y aislamiento entre gimnasios (404)."}],"ejemplo":[],"qa":[{"q":"¿Qué verifica el test de `roles: ['ADMIN']` en el sign-up público y por qué los datos de test llevan sufijo único?","a":"Que la API ignora ese campo y no convierte al usuario en admin; el sufijo único evita chocar con otros tests o datos existentes."}]},{"title":"Ciclo de trabajo con tickets (Linear, ramas, PR)","que":[{"t":"p","x":"Ticket `GYM-XX` en Linear → rama `feature/GYM-XX-descripcion` desde `dev`/main → commits `GYM-XX: resumen en imperativo` → push → Pull Request → revisión → merge (recién ahí el ticket pasa a Done). Flujo de ramas: feature → dev → qas → main. Levantar el proyecto: Docker Desktop, `db:up` + `db:migrate` (+ `seed:admin` la primera vez), `npm run dev`, IP en `app/.env`, `npx expo start`, QR con la cámara de iOS."}],"ejemplo":[],"qa":[{"q":"¿Cómo se nombran ramas y commits en el flujo con Linear y cuándo pasa una historia a Done?","a":"Rama `feature/GYM-XX-...` y commits con prefijo `GYM-XX:`; Done solo al hacer merge."}]},{"title":"Plan de aprendizaje: predecir, correr, romper, explicar","que":[{"t":"p","x":"Cada sesión: predecir en la bitácora, correr, romper algo a propósito y explicar con tus palabras; el que aprende escribe el código y la IA da pistas, no soluciones."}],"ejemplo":[],"qa":[{"q":"¿Cuáles son los cuatro pasos de cada sesión?","a":"Predecir, correr, romper y explicar."}]},{"title":"Convenciones de dependencias (~, expo install)","que":[{"t":"p","x":"`~57.0.25` permite parches pero no minor nuevos; con Expo se instala con `npx expo install` para versiones compatibles con el SDK."}],"ejemplo":[],"qa":[{"q":"¿Qué significa `~` en una versión npm?","a":"Acepta actualizaciones de parche dentro de la misma minor."}]},{"title":"React: useState, useMemo, contexto","que":[{"t":"p","x":"`useState` es una variable que al cambiar redibuja la pantalla; `useMemo` recalcula solo si cambian las dependencias (rendimiento); el contexto comparte `me` sin pasarlo pantalla por pantalla; `useEffect` con `[]` corre una vez al montar."}],"ejemplo":[],"qa":[{"q":"¿Qué hace `useMemo(fn, [dep])`?","a":"Memoriza el resultado y lo recalcula solo si cambia `dep`."}]},{"title":"Sistema de diseño con tokens y contraste WCAG","que":[{"t":"p","x":"Colores, tipografía y espaciado viven en `tokens.ts`; el modo claro se tipa como `typeof dark` para obligar a tener las mismas claves; `check-contrast.mjs` verifica contraste WCAG."}],"ejemplo":[],"qa":[{"q":"¿Qué garantiza `const light: typeof dark`?","a":"Que el modo claro tenga exactamente las mismas claves que el oscuro."}]},{"title":"Diagramas Excalidraw desde JSON","que":[{"t":"p","x":"Los `*.view.json` (elementos simplificados) se convierten con `to_excalidraw.py` en `.excalidraw`: rectángulos con etiqueta, flechas con bindings, `cameraUpdate` inicial, paleta por tipo (azul UI, morado API, teal datos)."}],"ejemplo":[],"qa":[{"q":"¿Cómo regenerar los `.excalidraw`?","a":"Con `python diagramas/to_excalidraw.py`."}]},{"title":"Tipos y desestructuración en TS","que":[{"t":"p","x":"`type Me = { id: string; roles: string[] ... }` equivale a un dataclass/TypedDict; `T | null` es `Optional[T]`; la desestructuración `const { name, roles } = cesar` equivale a asignar por clave. Node no valida tipos (solo los borra)."}],"ejemplo":[],"qa":[{"q":"¿Qué es `last: {...} | null` en Python?","a":"`Optional[...]`."}]},{"title":"map/filter/reduce/some y funciones flecha","que":[{"t":"p","x":"`reduce` suma totales, `map` proyecta, `filter` selecciona, `some`/`includes` comprueba; las funciones flecha y los template strings; cuidado con acceder a `.last.kg` cuando `last` es null."}],"ejemplo":[],"qa":[{"q":"¿Equivalente Python de `arr.map(e => e.name)`?","a":"`[e[\"name\"] for e in arr]`."}]},{"title":"Event loop en JS: orden de A, B, C, D","que":[{"t":"p","x":"`console.log` síncrono primero, luego microtareas (`Promise.then`) y luego macrotareas (`setTimeout 0`): orden A, D, C, B. `async/await` con `fetch`, `try/catch` para API apagada; `await` top-level es posible en módulos ES."}],"ejemplo":[],"qa":[{"q":"¿Qué se ejecuta antes: `Promise.then` o `setTimeout(0)`?","a":"`Promise.then` (microtarea) va antes que el `setTimeout` (macrotarea)."}]}]},{"title":"Proyecto price_scout y otros proyectos de práctica","concepts":[{"title":"Arquitectura modular app/{db, scrape, logic, notify}","que":[{"t":"p","x":"Cada módulo con una responsabilidad: base de datos, scraping, lógica de alertas pura y notificaciones; `main.py` orquesta, `cli.py` ofrece subcomandos. Mantiene la lógica de negocio separada de IO."}],"ejemplo":[],"qa":[{"q":"¿Por qué aislar `should_alert` en su propio módulo?","a":"Porque es lógica pura fácil de testear, independiente del scraping y de Telegram."}]},{"title":"Lógica de alertas: precio objetivo y % de caída","que":[{"t":"p","x":"Alerta si `new_price <= target_price` o si `(last-new)/last*100 >= alert_drop_pct`. Devuelve `(bool, mensaje)` tipado `tuple[bool, str]`."}],"ejemplo":[],"qa":[{"q":"¿Cómo calculas el % de caída de precio?","a":"`(precio_anterior - precio_nuevo) / precio_anterior * 100`."}]},{"title":"Anti-spam: no alertar si el precio no cambió","que":[{"t":"p","x":"Se guarda siempre el historial, pero si `abs(last - price) < 1e-9` se omite la alerta. Se compara con tolerancia porque son floats."}],"ejemplo":[],"qa":[{"q":"¿Por qué comparar floats con tolerancia?","a":"Por el error de representación binaria; se usa `abs(a-b) < epsilon`."}]},{"title":"Aislar errores por ítem en un lote","que":[{"t":"p","x":"En el bucle principal cada producto va en su `try/except` para que un fallo se loguee y no detenga el resto; se registran inicio/fin."}],"ejemplo":[],"qa":[{"q":"¿Por qué un `try/except` por producto dentro del bucle?","a":"Para que el error de uno no aborte el procesamiento de los demás."}]},{"title":"argparse con subcomandos y set_defaults(func=)","que":[{"t":"p","x":"`add_subparsers(dest=\"cmd\", required=True)` crea comandos (`add`, `add-url`, `bulk-add`, `list`); cada uno asigna su handler con `set_defaults(func=...)` y `main` hace `args.func(args)`."}],"ejemplo":[],"qa":[{"q":"¿Cómo asocias cada subcomando a su función en argparse?","a":"Con `parser.set_defaults(func=handler)` y luego `args.func(args)`."}]},{"title":"Carga masiva con resumen y archivo de fallidos","que":[{"t":"p","x":"Un generador `iter_rows()` lee `.txt` o `.csv`; por URL: skip duplicados, autodetecta, inserta o registra fallo; al final imprime RESUMEN (agregados/duplicados/fallidos) y escribe `bulk_failed.txt`. Usa `utf-8-sig` para CSV con BOM."}],"ejemplo":[],"qa":[{"q":"¿Por qué guardar las URLs fallidas en un archivo?","a":"Para poder reintentarlas o revisarlas después sin repetir todo el lote."}]},{"title":"Playwright headless y bloqueo de recursos","que":[{"t":"p","x":"Lanzar Chromium sin interfaz, con user-agent propio, timeouts y `page.route(\"**/*\", handler)` que aborta imágenes/media/fuentes para ir más rápido. Se envuelve en un context manager que cierra contexto y navegador."}],"ejemplo":[],"qa":[{"q":"¿Por qué bloquear imágenes y fuentes al hacer scraping?","a":"Para reducir tiempo y ancho de banda cuando solo interesan los datos."}]},{"title":"Estrategia de autodetección en cascada (fallback chain)","que":[{"t":"p","x":"Primero reglas específicas por dominio, luego JSON-LD (`script[type=\"application/ld+json\"]`, suele ser lo más fiable), luego selectores CSS candidatos, y al final \"no detectado\". El \"modo\" detectado se guarda para reutilizar al re-scrapear. Plan: añadir LLM como último fallback con caché."}],"ejemplo":[],"qa":[{"q":"¿Por qué probar JSON-LD antes que selectores CSS?","a":"Porque es datos estructurados estándar, más estable que clases CSS que cambian."}]},{"title":"Extraer precio de JSON-LD anidado","que":[{"t":"p","x":"Recursión sobre listas, `@graph` y `offers` (dict o lista); se prueba `price`, `lowPrice`, `highPrice`, `priceSpecification`. También un JSON de producto de Shopify con `variants` (precio en centavos /100; elegir variante completa sobre decants)."}],"ejemplo":[],"qa":[{"q":"¿Por qué la extracción de JSON-LD es recursiva?","a":"Porque los datos pueden venir en listas, dentro de `@graph` o `offers` anidados."}]},{"title":"Importación opcional con degradación elegante","que":[{"t":"p","x":"Para dependencias que cambian de API (`playwright_stealth`) se prueban candidatos con `importlib` y se deja una función no-op por defecto, de modo que la falta de la librería no rompe el programa."}],"ejemplo":[],"qa":[{"q":"¿Cómo haces una dependencia opcional sin romper la app?","a":"Intentas importarla en `try/except` y defines un reemplazo no-op por defecto."}]},{"title":"Notificaciones por Telegram con requests","que":[{"t":"p","x":"`POST https://api.telegram.org/bot<TOKEN>/sendMessage` con `chat_id` y `text`; `raise_for_status()` convierte HTTP de error en excepción; si faltan variables de entorno se degrada sin romper. `getUpdates` sirve para depurar el `chat_id`."}],"ejemplo":[],"qa":[{"q":"¿Qué hace `r.raise_for_status()`?","a":"Lanza una excepción si la respuesta HTTP fue 4xx/5xx."}]},{"title":"IA/LLM como fallback en productos, con caché (y RAG, tool calling)","que":[{"t":"p","x":"Función async que llama a la API de un LLM (modelo económico) para una tarea concreta (detectar un selector CSS). Estrategia: reglas primero → LLM → manual; cachear resultados y medir coste/tokens. Conceptos: salida JSON estructurada, streaming, embeddings + búsqueda semántica; RAG (recuperar documentos y responder citando fuentes); function/tool calling (el modelo decide qué función llamar); validar siempre las salidas de la IA."}],"ejemplo":[],"qa":[{"q":"¿Por qué cachear los resultados de un LLM y poner reglas antes del LLM? ¿Qué es RAG?","a":"Para reducir coste y latencia; el LLM solo se usa cuando las reglas simples fallan. RAG: recuperar fragmentos relevantes de tus documentos y dárselos al modelo para que responda citando la fuente."}]},{"title":"Regresión lineal simple con scikit-learn","que":[{"t":"p","x":"`LinearRegression().fit(X, y)` ajusta una recta; la pendiente (`coef_`) indica la tendencia (sube/baja) y `predict` estima un valor futuro. Sirve para series simples como precios históricos."}],"ejemplo":[],"qa":[{"q":"¿Qué indica el coeficiente `coef_` de una regresión lineal sobre precios?","a":"La pendiente: si es negativa el precio tiende a bajar, si es positiva a subir."}]},{"title":"Gestor de gastos en consola (CRUD en memoria)","que":[{"t":"p","x":"Proyecto inicial: menú con `while True`, `input`, lista de dicts `{\"nombre\",\"monto\"}`, añadir/listar/eliminar y salir con `break`. Bugs típicos: usar `gastos` sin definirla, modificar una lista mientras se recorre, eliminar sin `break`."}],"ejemplo":[],"qa":[{"q":"¿Qué riesgo hay en hacer `pop` dentro de un `for` sobre la misma lista?","a":"Mutar la lista mientras se itera puede saltar elementos o fallar."}]},{"title":"Extraer facturas de texto libre (datos de prueba)","que":[{"t":"p","x":"Archivos `.txt` con líneas \"cantidad producto\" mezcladas con texto de saludo y un archivo roto (emojis) sirven como casos reales/borde para un lector de facturas: parseo línea a línea, tolerar ruido y manejar encodings."}],"ejemplo":[],"qa":[{"q":"¿Qué tipos de casos borde tendría un lector de facturas?","a":"Líneas sin cantidad, texto de saludo, productos desconocidos, caracteres especiales/emojis y archivos vacíos o corruptos."}]}]}]});
